package chainledger

import (
	"encoding/json"
	"io"
	"sort"
	"strings"
	"unicode/utf8"
)

// ImportLineage decodes a lineage document in the same JSON shape the exports
// produce and returns a brand-new, independent lineage graph holding exactly
// the document's nodes and direct dependencies. The returned map works with
// every existing operation: Register, Rename, Unregister, Impacts,
// ImpactsWithCutoffs, Upstreams, CommonUpstreams, Roots and both exports. The
// caller's own graph is never read or modified — import only creates a new map.
//
// The document is one single JSON object with two array fields:
//
//   - "nodes": dataset names. Every listed node exists in the new graph,
//     including independent datasets with no dependency in either direction.
//     A name listed more than once counts once.
//   - "edges": direct dependencies written {"from": upstream, "to": derived},
//     the same direction the exports use. Each edge becomes the derived
//     dataset's direct upstream (Parents) and, mirrored, the upstream's direct
//     downstream (Children). The same dependency listed more than once counts
//     once. The endpoint fields are recognized by their exact decoded key
//     name: only keys that decode to precisely "from" and "to" (any JSON
//     escape spelling included) set the endpoints. Case variants such as
//     "From" or "TO" are unknown fields — ignored like any other unknown
//     field, their values never validated or used — so an edge carrying only
//     a case variant is rejected as missing that endpoint.
//
// Import scope is exactly the document: nothing is invented, inferred or
// completed. A document produced by a source-scoped export rebuilds only that
// part of the lineage — other sources and downstreams the export omitted are
// not restored. Direct relations and longer branches through intermediate
// nodes are kept together, so explanation paths are still chosen by the
// existing query rules (fewest edges, then the lexicographically smallest full
// path in Go string order).
//
// Nodes and edges may appear in the document in any order; the result is
// independent of that order. Every node's direct upstream and downstream
// lists are stored in Go string order, so a graph imported from a valid export
// document re-exports byte-identical text for the same target or source-target
// pair.
//
// Names are identified by their exact decoded JSON value: matching is
// case-sensitive and spaces, Chinese characters, quotes, backslashes and
// newlines are preserved verbatim — never trimmed or rewritten. The input
// must be valid UTF-8 and hold exactly one complete JSON object; "nodes" and
// "edges" must both be present, each as an array of the correct element type
// (null is not an array). Two empty arrays import successfully as an empty,
// ready-to-register graph.
//
// The whole document is validated before the graph is returned, so every
// failure yields a nil graph and an error describing the document problem,
// never a partial graph:
//
//   - Empty or whitespace-only text, text that is not valid UTF-8, malformed
//     JSON, more than one JSON value, a non-object document, a duplicated
//     object key, a missing or null array, or an element of the wrong type is
//     rejected.
//   - An empty node name is rejected as a missing name.
//   - A name (a node name, or an edge's "from" or "to") containing an unpaired
//     Unicode surrogate escape is rejected. encoding/json rewrites a lone
//     \uD800–\uDFFF escape to the replacement character U+FFFD, so two
//     different bad names would silently collapse into one "�" and a bad edge
//     endpoint could match a real dataset named "�". A high-surrogate escape
//     is valid only immediately followed by the low-surrogate escape that
//     completes one character; a lone high, a lone low, a reversed pair, or a
//     pair broken by other characters or escapes is unpaired. The error says
//     so, names where the escape was found (node name, edge "from" or edge
//     "to") and quotes the offending escape in its original \uXXXX spelling,
//     so distinct bad names never share one replacement glyph. A real U+FFFD
//     character written directly or as a \uFFFD escape is valid, as is a
//     correctly paired \uD83D\uDE00: both spellings decode to the same one
//     character as a literal emoji, so a node written one way and an edge the
//     other still connect. The document text "\\uD800" (an escaped backslash
//     followed by letters) is an ordinary name containing no surrogate escape
//     and is kept verbatim.
//   - Both endpoints of every edge must be listed in nodes; an edge naming a
//     dataset the document does not list fails the whole import, and the error
//     names that dataset. Edges missing an endpoint are rejected the same way.
//   - A self-dependency or a dependency cycle of any length fails the whole
//     import; the error states that the lineage contains a cycle and names the
//     datasets on it.
func ImportLineage(text string) (map[string]*Lineage, error) {
	nodesRaw, edgesRaw, err := decodeLineageDocument(text)
	if err != nil {
		return nil, err
	}

	var nodeItems []json.RawMessage
	if err := json.Unmarshal(nodesRaw, &nodeItems); err != nil {
		return nil, errInvalid("lineage document nodes must be an array of JSON strings: " + err.Error())
	}
	var edgeItems []json.RawMessage
	if err := json.Unmarshal(edgesRaw, &edgeItems); err != nil {
		return nil, errInvalid(`lineage document edges must be an array of {"from": ..., "to": ...} objects: ` + err.Error())
	}

	// Build the de-duplicated node set. Each element must itself be a JSON
	// string (null is not a name). Names keep their exact decoded value: the
	// document was already checked to be valid UTF-8, so every decoded name is
	// the original value, with JSON unescaping applied (quotes, backslashes,
	// newlines and all). Unpaired \u surrogate escapes are rejected on the raw
	// text first: encoding/json accepts them and rewrites each one to U+FFFD,
	// so two different bad names would silently collapse into one.
	nodes := make(map[string]bool, len(nodeItems))
	for _, item := range nodeItems {
		trimmed := strings.TrimSpace(string(item))
		if !strings.HasPrefix(trimmed, `"`) {
			return nil, errInvalid("lineage document nodes must be an array of JSON strings")
		}
		name, err := unmarshalLineageName(item)
		if err != nil {
			return nil, err
		}
		if name == "" {
			return nil, errInvalid("dataset name is required")
		}
		nodes[name] = true
	}

	// Resolve every edge before constructing entries. Each element must be a
	// {"from": ..., "to": ...} object; both endpoints must be listed nodes.
	// De-duplicated dependencies only, independent of document order.
	dependencies := make(map[lineageExportEdge]bool, len(edgeItems))
	for _, item := range edgeItems {
		trimmed := strings.TrimSpace(string(item))
		if !strings.HasPrefix(trimmed, "{") {
			return nil, errInvalid(`lineage document edges must be an array of {"from": ..., "to": ...} objects`)
		}
		// Decode the object structurally without accepting endpoint strings:
		// the from/to values are then validated as names themselves, so an
		// unpaired surrogate escape in an endpoint fails the import instead of
		// silently matching a real "�" dataset. Keys are matched by their exact
		// decoded name through a map: only fields literally named "from" and
		// "to" (however escaped in the raw text) set the endpoints. A struct
		// unmarshal would also bind case variants like "From" or "FROM" to the
		// endpoint fields, letting an unknown field overwrite the declared
		// endpoints depending on member order; here they are unknown fields
		// like any other and their values never participate in the lineage.
		var edgeRaw map[string]json.RawMessage
		if err := json.Unmarshal(item, &edgeRaw); err != nil {
			return nil, errInvalid(`lineage document edges must be an array of {"from": ..., "to": ...} objects: ` + err.Error())
		}
		from, err := unmarshalEndpointName(edgeRaw["from"], "from")
		if err != nil {
			return nil, err
		}
		to, err := unmarshalEndpointName(edgeRaw["to"], "to")
		if err != nil {
			return nil, err
		}
		edge := lineageExportEdge{From: from, To: to}
		if edge.From == "" {
			return nil, errInvalid(`lineage document edge is missing its upstream endpoint ("from")`)
		}
		if edge.To == "" {
			return nil, errInvalid(`lineage document edge is missing its derived endpoint ("to")`)
		}
		if !nodes[edge.From] {
			return nil, errInvalid("edge endpoint not listed in nodes: " + edge.From)
		}
		if !nodes[edge.To] {
			return nil, errInvalid("edge endpoint not listed in nodes: " + edge.To)
		}
		dependencies[edge] = true
	}

	// Materialize the new graph with direct lists in Go string order. All
	// entries exist before any edge is attached, and a rejected import returns
	// nil, so a caller can never observe a partially filled graph.
	graph := make(map[string]*Lineage, len(nodes))
	for name := range nodes {
		graph[name] = &Lineage{Dataset: name}
	}
	for edge := range dependencies {
		graph[edge.To].Parents = append(graph[edge.To].Parents, edge.From)
		graph[edge.From].Children = append(graph[edge.From].Children, edge.To)
	}
	for _, entry := range graph {
		sort.Strings(entry.Parents)
		sort.Strings(entry.Children)
	}

	// Cycles of any length (self dependencies included) are rejected with the
	// datasets on one such cycle named deterministically.
	if cycle := findLineageCycle(graph); cycle != nil {
		return nil, errInvalid("lineage contains a cycle: " + strings.Join(cycle, " -> "))
	}
	return graph, nil
}

// decodeLineageDocument runs the document-level checks and returns the raw
// JSON values of the nodes and edges arrays: the text must be non-empty, valid
// UTF-8, exactly one complete JSON object with no duplicated object key, and
// both fields must be present as arrays (null rejected, element types are
// checked by the caller's typed unmarshal).
func decodeLineageDocument(text string) (json.RawMessage, json.RawMessage, error) {
	if strings.TrimSpace(text) == "" {
		return nil, nil, errInvalid("lineage document is empty: expected one JSON object with nodes and edges arrays")
	}
	// encoding/json silently rewrites invalid UTF-8 into U+FFFD instead of
	// failing, and two byte-different names could then collapse into one, so
	// the whole text is checked before anything is decoded.
	if !utf8.ValidString(text) {
		return nil, nil, errInvalid("lineage document is not valid UTF-8")
	}
	if err := rejectDuplicateKeys(text); err != nil {
		return nil, nil, err
	}

	var raw map[string]json.RawMessage
	if err := json.Unmarshal([]byte(text), &raw); err != nil {
		return nil, nil, errInvalid("lineage document must be one complete JSON object: " + err.Error())
	}

	nodes, ok := raw["nodes"]
	if !ok {
		return nil, nil, errInvalid(`lineage document is missing the "nodes" array`)
	}
	edges, ok := raw["edges"]
	if !ok {
		return nil, nil, errInvalid(`lineage document is missing the "edges" array`)
	}
	if err := requireJSONArray(nodes, "nodes"); err != nil {
		return nil, nil, err
	}
	if err := requireJSONArray(edges, "edges"); err != nil {
		return nil, nil, err
	}
	return nodes, edges, nil
}

// requireJSONArray rejects a field that is null or whose value is not a JSON
// array; element types inside the array are validated by typed unmarshalling.
func requireJSONArray(raw json.RawMessage, field string) error {
	trimmed := strings.TrimSpace(string(raw))
	switch {
	case trimmed == "null":
		return errInvalid("lineage document field " + field + " must be an array, got null")
	case !strings.HasPrefix(trimmed, "["):
		return errInvalid("lineage document field " + field + " must be an array")
	}
	return nil
}

// decodeLineageName decodes one JSON string token (a node name or an edge
// endpoint) into its exact Go value, rejecting unpaired \u surrogate escapes
// before json.Unmarshal can touch the text.
//
// encoding/json accepts a lone \uD800–\uDFFF escape and rewrites it to the
// replacement character U+FFFD: two byte-different bad names would then
// collapse into one "�", and a bad edge endpoint would silently match a real
// dataset named "�". The raw token is therefore scanned first. A high
// surrogate escape is valid only when it is immediately followed by the low
// surrogate escape that together represent one character; a lone high, a lone
// low, a reversed pair, or a pair broken by other escapes or characters is
// unpaired. On success ok is true with the decoded value; when the token
// contains an unpaired escape, ok is still true, name is empty and badEscape
// holds the escape in its original \uXXXX spelling; ok is false only when the
// token is not a JSON string. The token was extracted from an already
// validated document, so json.Unmarshal cannot fail for a token that starts
// with a quote.
func decodeLineageName(raw json.RawMessage) (name, badEscape string, ok bool) {
	if !strings.HasPrefix(strings.TrimSpace(string(raw)), `"`) {
		return "", "", false
	}
	if bad := firstUnpairedSurrogate(string(raw)); bad != "" {
		return "", bad, true
	}
	var decoded string
	if err := json.Unmarshal(raw, &decoded); err != nil {
		return "", "", false
	}
	return decoded, "", true
}

// firstUnpairedSurrogate scans the raw text of one JSON string token and
// returns the first unpaired \u surrogate escape in its original spelling
// ("" when every surrogate escape is correctly paired). Escaped backslashes
// are skipped as a unit, so "\\ud800" is literal backslash-plus-letters, not a
// surrogate escape.
func firstUnpairedSurrogate(token string) string {
	for i := 0; i < len(token); {
		if token[i] != '\\' {
			i++
			continue
		}
		if i+1 >= len(token) {
			i++
			continue
		}
		switch token[i+1] {
		case '\\':
			// An escaped backslash consumes both characters; whatever follows
			// is literal text, including a "\ud800"-looking sequence.
			i += 2
			continue
		case 'u':
			r, valid := decodeJSONHexU(token, i)
			if !valid {
				i += 2 // malformed token; the document-level decode already rejected it
				continue
			}
			switch {
			case r >= 0xDC00 && r <= 0xDFFF:
				return token[i : i+6] // lone low surrogate
			case r >= 0xD800 && r <= 0xDBFF:
				// A high surrogate is valid only when the very next token is a
				// low surrogate escape; any other escape, character or end of
				// string leaves it unpaired.
				next, nextValid := decodeJSONHexU(token, i+6)
				if !nextValid || next < 0xDC00 || next > 0xDFFF {
					return token[i : i+6]
				}
				i += 12
				continue
			}
			i += 6
			continue
		}
		i += 2 // any other JSON escape (\", \n, \t, ...)
	}
	return ""
}

// decodeJSONHexU decodes the \uXXXX escape beginning at token[pos] (token[pos]
// is a backslash and token[pos+1] the letter u) into its code point.
func decodeJSONHexU(token string, pos int) (rune, bool) {
	if pos+6 > len(token) || token[pos] != '\\' || token[pos+1] != 'u' {
		return 0, false
	}
	var r rune
	for k := pos + 2; k < pos+6; k++ {
		var digit rune
		switch {
		case token[k] >= '0' && token[k] <= '9':
			digit = rune(token[k] - '0')
		case token[k] >= 'a' && token[k] <= 'f':
			digit = rune(token[k]-'a') + 10
		case token[k] >= 'A' && token[k] <= 'F':
			digit = rune(token[k]-'A') + 10
		default:
			return 0, false
		}
		r = r*16 + digit
	}
	return r, true
}

// unmarshalLineageName decodes one nodes-array element that already passed the
// string-token guard. An unpaired surrogate fails the whole import with an
// error that says the node name held an unpaired surrogate escape and quotes
// the escape in its original \uXXXX spelling.
func unmarshalLineageName(raw json.RawMessage) (string, error) {
	name, badEscape, ok := decodeLineageName(raw)
	if !ok {
		return "", errInvalid("lineage document nodes must be an array of JSON strings")
	}
	if badEscape != "" {
		return "", errInvalid("lineage document node name contains an unpaired Unicode surrogate escape '" +
			badEscape + "'; surrogate escapes are valid only as a matched " +
			`\uXXXX\uYYYY high-low pair`)
	}
	return name, nil
}

// unmarshalEndpointName decodes one edge endpoint ("from" or "to"). A missing
// or null value returns "" like an absent field so the existing
// missing-endpoint checks report it; a present non-string value keeps the
// edges type error; an unpaired surrogate fails the import, naming the
// endpoint it came from and quoting the original escape.
func unmarshalEndpointName(raw json.RawMessage, endpoint string) (string, error) {
	trimmed := strings.TrimSpace(string(raw))
	if trimmed == "" || trimmed == "null" {
		return "", nil
	}
	name, badEscape, ok := decodeLineageName(raw)
	if !ok {
		return "", errInvalid(`lineage document edges must be an array of {"from": ..., "to": ...} objects: ` +
			`endpoint "` + endpoint + `" must be a JSON string`)
	}
	if badEscape != "" {
		return "", errInvalid(`lineage document edge "` + endpoint + `" endpoint contains an ` +
			"unpaired Unicode surrogate escape '" + badEscape +
			"'; surrogate escapes are valid only as a matched " +
			`\uXXXX\uYYYY high-low pair`)
	}
	return name, nil
}

// objectFrame tracks one container during the structural key scan: whether it
// is an object (arrays need no key tracking), whether the next string token is
// that object's key, and the keys already seen in it.
type objectFrame struct {
	object    bool
	expectKey bool
	keys      map[string]bool
}

// rejectDuplicateKeys tokenizes the text and rejects any JSON object that
// repeats a key, any document whose top-level value is not an object, and any
// trailing JSON value after the closing object. encoding/json accepts all
// three silently (last key wins; null decodes into a map as no value at all;
// trailing values are rejected by Unmarshal but with a generic message), so
// the explicit scan makes document problems deterministic.
func rejectDuplicateKeys(text string) error {
	dec := json.NewDecoder(strings.NewReader(text))
	// Numbers are only structure here, never values: keep them as raw
	// json.Number literals so a syntactically valid number of any magnitude
	// (1e400, a hundred-digit integer) tokenizes without a float64 range
	// error. The scanner still validates the literal itself, so 01, 1e or
	// NaN remain malformed JSON and fail the document.
	dec.UseNumber()
	var stack []objectFrame
	rootClosed := false
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			if len(stack) != 0 || !rootClosed {
				return errInvalid("lineage document must be one complete JSON object")
			}
			return nil
		}
		// Anything at all after the root object closes is a second value or
		// garbage, whether tokenized as a token or as a scan error.
		if rootClosed {
			return errInvalid("lineage document must hold exactly one JSON object")
		}
		if err != nil {
			return errInvalid("lineage document must be one complete JSON object: " + err.Error())
		}

		switch t := tok.(type) {
		case json.Delim:
			switch t {
			case '{':
				stack = append(stack, objectFrame{object: true, expectKey: true, keys: map[string]bool{}})
			case '[':
				if len(stack) == 0 {
					return errInvalid("lineage document must be a JSON object with nodes and edges arrays, got an array")
				}
				stack = append(stack, objectFrame{})
			case '}', ']':
				if len(stack) == 0 {
					return errInvalid("lineage document has an unmatched " + string(t))
				}
				stack = stack[:len(stack)-1]
				if len(stack) == 0 {
					if t != '}' {
						return errInvalid("lineage document must be a JSON object with nodes and edges arrays")
					}
					rootClosed = true
				} else if stack[len(stack)-1].object {
					// A nested container was this object member's value; the
					// next member, if any, starts with a key.
					stack[len(stack)-1].expectKey = true
				}
			}
		case string:
			if len(stack) == 0 {
				return errInvalid("lineage document must be a JSON object with nodes and edges arrays, got a string")
			}
			top := &stack[len(stack)-1]
			if !top.object {
				continue // string element of an array; members are delimiter-tracked
			}
			if !top.expectKey {
				top.expectKey = true // string value consumed; a key may follow
				continue
			}
			if top.keys[t] {
				return errInvalid("lineage document contains a duplicated object key: " + t)
			}
			top.keys[t] = true
			top.expectKey = false
		default: // number, bool, nil
			if len(stack) == 0 {
				return errInvalid("lineage document must be a JSON object with nodes and edges arrays")
			}
			if stack[len(stack)-1].object {
				stack[len(stack)-1].expectKey = true
			}
		}
	}
}

// findLineageCycle returns the datasets on one directed cycle written in the
// actual derivation direction (upstream -> derived), with the smallest-named
// dataset on the cycle first and repeated last, or nil when the graph is
// acyclic. Every node on a cycle reaches itself by following parent edges, so
// a depth-first walk with a per-path stack catches a back edge of any length,
// including a self dependency. Nodes are visited in Go string order and parent
// lists are already sorted, so the reported cycle is independent of the
// document's node and edge ordering.
func findLineageCycle(graph map[string]*Lineage) []string {
	color := make(map[string]int, len(graph)) // 0 unseen, 1 on current path, 2 done
	var stack []string
	var found []string

	var visit func(node string) bool
	visit = func(node string) bool {
		color[node] = 1
		stack = append(stack, node)
		for _, parent := range graph[node].Parents {
			switch color[parent] {
			case 0:
				if visit(parent) {
					return true
				}
			case 1:
				// A back edge to a node on the current path closes a cycle:
				// parent ... node, with node deriving from parent.
				start := 0
				for stack[start] != parent {
					start++
				}
				found = append([]string(nil), stack[start:]...)
				return true
			}
		}
		stack = stack[:len(stack)-1]
		color[node] = 2
		return false
	}

	names := make([]string, 0, len(graph))
	for name := range graph {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		if color[name] == 0 && visit(name) {
			return derivationCycle(found)
		}
	}
	return nil
}

// derivationCycle converts a closed cycle segment discovered while following
// parent edges into the derivation direction, then rotates it so the
// smallest-named dataset comes first (and stays last). A parent-direction
// segment [p0, p1, ..., pk] closes with pk deriving from p0, so the derivation
// runs p0 -> pk -> ... -> p1 -> p0.
func derivationCycle(parentPath []string) []string {
	body := make([]string, 0, len(parentPath)+1)
	body = append(body, parentPath[0])
	for i := len(parentPath) - 1; i >= 1; i-- {
		body = append(body, parentPath[i])
	}

	min := 0
	for i := 1; i < len(body); i++ {
		if body[i] < body[min] {
			min = i
		}
	}
	rotated := make([]string, 0, len(body)+1)
	rotated = append(rotated, body[min:]...)
	rotated = append(rotated, body[:min]...)
	rotated = append(rotated, body[min])
	return rotated
}

package chainledger

import (
	"reflect"
	"strings"
	"testing"
)

// These tests pin down how an edge object's endpoint fields are recognized:
// only keys that decode to exactly "from" and "to" set the upstream and
// derived endpoints. Case variants ("From", "FROM", "To", "TO", ...) are
// unknown fields like any other — ignored, their values never validated or
// used — so they can neither add, move nor invent a dependency, and an edge
// that carries only a case variant is rejected as missing that endpoint.
// Recognition happens on the decoded key name, so a JSON \u escape spelling
// of "from"/"to" still names the endpoint, while an escaped backslash turns
// the same text into an ordinary unknown field.

// A document that carries both the correct lowercase endpoints and case
// variants imports only the lowercase relation. The variant may sit before or
// after the real fields; either way report depends on raw alone, other stays
// an independent node, and nothing the variant names enters the lineage. The
// result is checked through the direct lists, the queries and the re-exported
// document — not merely through the absence of an error.
func TestImportLineageCaseVariantFieldsAreUnknown(t *testing.T) {
	documents := []struct {
		name string
		text string
	}{
		{
			"From before from",
			`{"nodes":["raw","other","report"],"edges":[` +
				`{"From":"other","from":"raw","to":"report"}]}`,
		},
		{
			"From after from",
			`{"nodes":["raw","other","report"],"edges":[` +
				`{"from":"raw","to":"report","From":"other"}]}`,
		},
		{
			"FROM between the real fields",
			`{"nodes":["raw","other","report"],"edges":[` +
				`{"from":"raw","FROM":"other","to":"report"}]}`,
		},
		{
			"To variant does not retarget the derived endpoint",
			`{"nodes":["raw","other","report"],"edges":[` +
				`{"from":"raw","To":"other","to":"report"}]}`,
		},
		{
			"TO variant after the real fields",
			`{"nodes":["raw","other","report"],"edges":[` +
				`{"from":"raw","to":"report","TO":"other"}]}`,
		},
		{
			"variants on both endpoints at once",
			`{"nodes":["raw","other","report"],"edges":[` +
				`{"FROM":"other","from":"raw","TO":"other","to":"report"}]}`,
		},
	}

	for _, tc := range documents {
		t.Run(tc.name, func(t *testing.T) {
			graph := mustImport(t, tc.text)
			assertConsistent(t, graph)

			// Exactly the three declared nodes exist; the variant did not
			// invent a node or attach other to anything.
			if got, want := len(graph), 3; got != want {
				t.Fatalf("graph has %d nodes %v, want %d", got, graph, want)
			}
			assertEntry(t, graph, "raw", nil, []string{"report"})
			assertEntry(t, graph, "report", []string{"raw"}, nil)
			assertEntry(t, graph, "other", nil, nil)

			// Queries see only the lowercase relation, from both directions.
			upstreams := mustUpstreams(t, graph, "report")
			if got, want := upstreamNames(upstreams), []string{"raw"}; !reflect.DeepEqual(got, want) {
				t.Errorf("upstreams of report = %v, want %v", got, want)
			}
			assertUpstreamOnce(t, upstreams, "raw", 1, []string{"raw", "report"})
			impacts := mustImpacts(t, graph, "raw")
			assertImpactOnce(t, impacts, "report", 1, []string{"raw", "report"})
			if got := mustImpacts(t, graph, "other"); len(got) != 0 {
				t.Errorf("other must stay independent, impacts = %v", impactNames(got))
			}
			if got, want := Roots(graph), []string{"other", "raw"}; !reflect.DeepEqual(got, want) {
				t.Errorf("Roots = %v, want %v", got, want)
			}

			// The re-exported document holds exactly the lowercase relation.
			out := mustExport(t, graph, "report")
			if want := `{"nodes":["raw","report"],"edges":[{"from":"raw","to":"report"}]}`; out != want {
				t.Errorf("export = %s, want %s", out, want)
			}
		})
	}
}

// A case variant whose value names a dataset the document does not list is
// still just an unknown field: the unregistered name is not validated against
// the node set, no node is invented for it, and the real endpoints alone
// decide the lineage.
func TestImportLineageCaseVariantNamingUnlistedDatasetStaysOut(t *testing.T) {
	text := `{"nodes":["raw","report"],"edges":[` +
		`{"from":"raw","to":"report","From":"ghost","TO":"phantom"}]}`

	graph := mustImport(t, text)
	assertConsistent(t, graph)

	if got, want := len(graph), 2; got != want {
		t.Fatalf("graph has %d nodes %v, want %d", got, graph, want)
	}
	assertEntry(t, graph, "raw", nil, []string{"report"})
	assertEntry(t, graph, "report", []string{"raw"}, nil)
	for _, leaked := range []string{"ghost", "phantom"} {
		if _, ok := graph[leaked]; ok {
			t.Errorf("case-variant value %q leaked into the graph as a node", leaked)
		}
		if _, err := Impacts(graph, leaked); err == nil ||
			!strings.Contains(err.Error(), leaked) {
			t.Errorf("query for variant value %q must fail as unregistered, got %v", leaked, err)
		}
	}
}

// Unknown edge fields are ignored wholesale, whatever their values look like:
// an unregistered name, a number, null, a nested object (even one holding its
// own from/to members), an array, or a string containing an unpaired
// surrogate escape. None of these trigger the name-type, missing-endpoint or
// name-encoding checks, because those checks apply to endpoints only, and
// none of the node- or dependency-looking content enters the graph.
func TestImportLineageUnknownEdgeFieldValuesNeverValidated(t *testing.T) {
	text := `{"nodes":["raw","mid","report"],"edges":[` +
		`{"from":"raw","to":"mid",` +
		`"From":"ghost","TO":42,"note":null,"flag":true,` +
		`"meta":{"from":"phantom","to":"specter"},"list":["phantom","specter"],` +
		`"bad":"\ud800"},` +
		`{"from":"mid","to":"report","From":["array","of","names"]}]}`

	graph := mustImport(t, text)
	assertConsistent(t, graph)

	if got, want := len(graph), 3; got != want {
		t.Fatalf("graph has %d nodes %v, want %d", got, graph, want)
	}
	assertEntry(t, graph, "raw", nil, []string{"mid"})
	assertEntry(t, graph, "mid", []string{"raw"}, []string{"report"})
	assertEntry(t, graph, "report", []string{"mid"}, nil)

	// Content that merely looks like nodes and dependencies inside unknown
	// fields is not lineage.
	for _, leaked := range []string{"ghost", "phantom", "specter", "meta", "bad"} {
		if _, ok := graph[leaked]; ok {
			t.Errorf("unknown-field content %q leaked into the graph", leaked)
		}
	}

	// The declared relations drive queries and the re-exported document.
	assertImpactOnce(t, mustImpacts(t, graph, "raw"), "report", 2,
		[]string{"raw", "mid", "report"})
	assertUpstreamOnce(t, mustUpstreams(t, graph, "report"), "raw", 2,
		[]string{"raw", "mid", "report"})
	if got, want := mustExport(t, graph, "report"),
		`{"nodes":["mid","raw","report"],"edges":[{"from":"mid","to":"report"},`+
			`{"from":"raw","to":"mid"}]}`; got != want {
		t.Errorf("export = %s, want %s", got, want)
	}
}

// Ignoring unknown fields never relaxes the document-level checks: malformed
// JSON and duplicated object keys are still rejected, including when the
// problem sits inside an unknown field of an edge object — a repeated case
// variant is a duplicated key like any other.
func TestImportLineageUnknownEdgeFieldsStillStructurallyValidated(t *testing.T) {
	cases := []struct {
		name string
		text string
		want []string
	}{
		{
			"malformed unknown field value",
			`{"nodes":["raw","report"],"edges":[{"from":"raw","to":"report","note":}]}`,
			[]string{"JSON object"},
		},
		{
			"truncated inside unknown field",
			`{"nodes":["raw","report"],"edges":[{"from":"raw","to":"report","meta":{"a":1}`,
			[]string{"complete"},
		},
		{
			"duplicate case-variant key on an edge",
			`{"nodes":["raw","report"],"edges":[{"from":"raw","to":"report","From":"a","From":"b"}]}`,
			[]string{"duplicated", "From"},
		},
		{
			"duplicate key inside unknown edge field object",
			`{"nodes":["raw","report"],"edges":[{"from":"raw","to":"report","meta":{"m":1,"m":2}}]}`,
			[]string{"duplicated", "m"},
		},
		{
			"escaped spelling duplicates the variant key",
			`{"nodes":["raw","report"],"edges":[{"from":"raw","to":"report","From":1,"\u0046rom":2}]}`,
			[]string{"duplicated", "From"},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			assertImportFails(t, tc.text, tc.want...)
		})
	}
}

// Field recognition works on the decoded key name: writing "from" and "to"
// with legal \u escapes still sets the endpoints and connects the very same
// nodes, while doubling the backslash makes the key an ordinary literal text
// that names no endpoint — the edge then fails as missing its upstream field.
func TestImportLineageEndpointKeysRecognizedByDecodedName(t *testing.T) {
	t.Run("escaped spellings of from and to connect the endpoints", func(t *testing.T) {
		// The keys are written as "\u0066rom" and "\u0074o": both decode to
		// exactly "from" and "to", so they set the endpoints like the plain
		// spelling.
		text := `{"nodes":["raw","report"],"edges":[` +
			`{"\u0066rom":"raw","\u0074o":"report"}]}`
		graph := mustImport(t, text)
		assertConsistent(t, graph)
		if got, want := len(graph), 2; got != want {
			t.Fatalf("graph has %d nodes %v, want %d", got, graph, want)
		}
		assertEntry(t, graph, "raw", nil, []string{"report"})
		assertEntry(t, graph, "report", []string{"raw"}, nil)
		assertUpstreamOnce(t, mustUpstreams(t, graph, "report"), "raw", 1,
			[]string{"raw", "report"})
	})

	t.Run("partially escaped key still decodes to the endpoint name", func(t *testing.T) {
		// "f\u0072om" and "t\u006f": only some letters are escaped, the
		// decoded key is still exactly the endpoint name.
		text := `{"nodes":["raw","report"],"edges":[` +
			`{"f\u0072om":"raw","t\u006f":"report"}]}`
		graph := mustImport(t, text)
		assertEntry(t, graph, "raw", nil, []string{"report"})
		assertEntry(t, graph, "report", []string{"raw"}, nil)
	})

	t.Run("escaped backslash makes the key an unknown field", func(t *testing.T) {
		// The key decodes to the literal text from (backslash included), not
		// to "from", so the edge has no upstream endpoint at all.
		text := `{"nodes":["raw","report"],"edges":[` +
			`{"\\u0066rom":"raw","to":"report"}]}`
		assertImportFails(t, text, "missing", `"from"`)
	})

	t.Run("escaped backslash on the derived endpoint", func(t *testing.T) {
		text := `{"nodes":["raw","report"],"edges":[` +
			`{"from":"raw","\\u0074o":"report"}]}`
		assertImportFails(t, text, "missing", `"to"`)
	})
}

// An edge whose endpoint is provided only through a case variant is missing
// that endpoint: the whole import fails with a nil graph and an error naming
// the missing field, and valid edges earlier in the same document do not
// produce a partial graph.
func TestImportLineageOnlyCaseVariantEndpointFailsWholeImport(t *testing.T) {
	cases := []struct {
		name string
		text string
		want []string
	}{
		{
			"From instead of from",
			`{"nodes":["raw","report"],"edges":[{"From":"raw","to":"report"}]}`,
			[]string{"missing", `"from"`},
		},
		{
			"FROM instead of from",
			`{"nodes":["raw","report"],"edges":[{"FROM":"raw","to":"report"}]}`,
			[]string{"missing", `"from"`},
		},
		{
			"To instead of to",
			`{"nodes":["raw","report"],"edges":[{"from":"raw","To":"report"}]}`,
			[]string{"missing", `"to"`},
		},
		{
			"TO instead of to",
			`{"nodes":["raw","report"],"edges":[{"from":"raw","TO":"report"}]}`,
			[]string{"missing", `"to"`},
		},
		{
			"both endpoints only as variants",
			`{"nodes":["raw","report"],"edges":[{"From":"raw","To":"report"}]}`,
			[]string{"missing", `"from"`},
		},
		{
			"valid edges before the variant-only edge give no partial graph",
			`{"nodes":["raw","mid","report"],"edges":[` +
				`{"from":"raw","to":"mid"},{"From":"mid","to":"report"}]}`,
			[]string{"missing", `"from"`},
		},
		{
			"valid edges before a to-variant-only edge",
			`{"nodes":["raw","mid","report"],"edges":[` +
				`{"from":"raw","to":"mid"},{"from":"mid","TO":"report"}]}`,
			[]string{"missing", `"to"`},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			assertImportFails(t, tc.text, tc.want...)
		})
	}
}

// The error for a variant-only edge is the same missing-endpoint error a
// genuinely absent field produces, so a reader can tell which endpoint the
// document lacks.
func TestImportLineageVariantOnlyEdgeErrorMatchesMissingFieldError(t *testing.T) {
	absent := `{"nodes":["raw","report"],"edges":[{"to":"report"}]}`
	variant := `{"nodes":["raw","report"],"edges":[{"From":"raw","to":"report"}]}`

	_, errAbsent := ImportLineage(absent)
	_, errVariant := ImportLineage(variant)
	if errAbsent == nil || errVariant == nil {
		t.Fatal("want missing-endpoint errors for both documents")
	}
	if errAbsent.Error() != errVariant.Error() {
		t.Errorf("variant-only edge error %q differs from absent-field error %q",
			errVariant.Error(), errAbsent.Error())
	}
	if want := `lineage document edge is missing its upstream endpoint ("from")`; errVariant.Error() != want {
		t.Errorf("error = %q, want %q", errVariant.Error(), want)
	}
}

// Command import-lineage-example demonstrates the chainledger lineage
// library's lineage import: export one dataset's lineage as JSON, hand that
// text to ImportLineage to obtain a fresh independent graph, and keep using
// the new graph with the existing registration and query operations.
//
// This is a library feature, not a command-line query: the lineage text is
// fixed in code. Run it from the repository root with:
//
//	go run ./examples/import-lineage
package main

import (
	"fmt"
	"os"

	"github.com/asdhoaiqqq/chainledger-governance/chainledger"
)

func main() {
	// The source graph is an ordinary in-memory map; Register fills it in.
	graph := map[string]*chainledger.Lineage{}
	register := func(name string, parents ...string) {
		if err := chainledger.Register(graph, chainledger.Dataset{Name: name}, parents); err != nil {
			fmt.Fprintf(os.Stderr, "register %s: %v\n", name, err)
			os.Exit(1)
		}
	}

	// pre -> source; source derives a, b and report directly; a and the
	// b -> mid branch both feed report; report derives view. report also
	// depends on two independent sources that a source-scoped export omits.
	register("pre")
	register("source", "pre")
	register("a", "source")
	register("b", "source")
	register("mid", "b")
	register("extra")
	register("lone")
	register("report", "source", "a", "mid", "extra", "lone")
	register("view", "report")

	// A source-scoped export keeps only the source -> report routes.
	text, err := chainledger.ExportSourceTargetLineage(graph, "source", "report")
	if err != nil {
		fmt.Fprintf(os.Stderr, "export: %v\n", err)
		os.Exit(1)
	}
	fmt.Println("exported document:")
	fmt.Println(text)

	// Import turns the text into a brand-new graph. The caller's graph is not
	// touched, and the scope is exactly the document: pre, extra, lone and
	// view are not restored.
	imported, err := chainledger.ImportLineage(text)
	if err != nil {
		fmt.Fprintf(os.Stderr, "import: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("\ndatasets after import: %d (the export omitted pre, extra, lone and view)\n", len(imported))

	// The imported graph answers queries exactly like a registered one: the
	// direct source -> report edge wins on distance, and the longer branches
	// through a and b -> mid survive at their own distances.
	impacts, err := chainledger.Impacts(imported, "source")
	if err != nil {
		fmt.Fprintf(os.Stderr, "impacts: %v\n", err)
		os.Exit(1)
	}
	fmt.Println("\nImpacts(source) on the imported graph:")
	for _, im := range impacts {
		fmt.Printf("  %-7s distance=%d path=%v\n", im.Dataset, im.Distance, im.Path)
	}

	// Re-exporting the same source and target from the imported graph yields
	// byte-identical text.
	again, err := chainledger.ExportSourceTargetLineage(imported, "source", "report")
	if err != nil {
		fmt.Fprintf(os.Stderr, "re-export: %v\n", err)
		os.Exit(1)
	}
	if again == text {
		fmt.Println("\nre-export is byte-identical to the imported document")
	} else {
		fmt.Printf("\nre-export differs:\n%s\n%s\n", text, again)
	}

	// The new graph is independent and fully usable: register more datasets,
	// and query datasets the scoped document omitted as unregistered.
	if err := chainledger.Register(imported, chainledger.Dataset{Name: "newly"}, []string{"mid"}); err != nil {
		fmt.Fprintf(os.Stderr, "register into imported graph: %v\n", err)
		os.Exit(1)
	}
	fmt.Println("\nregistered newly into the imported graph; querying omitted datasets:")
	if _, err := chainledger.Upstreams(imported, "view"); err != nil {
		fmt.Printf("  Upstreams(view) error: %v\n", err)
	}
	// The caller's original graph is unchanged and still has every dataset.
	fmt.Printf("  original graph still holds %d datasets, imported graph holds %d\n", len(graph), len(imported))

	// Two empty arrays give an empty graph that is ready for registration.
	empty, err := chainledger.ImportLineage(`{"nodes":[],"edges":[]}`)
	if err != nil {
		fmt.Fprintf(os.Stderr, "empty import: %v\n", err)
		os.Exit(1)
	}
	if err := chainledger.Register(empty, chainledger.Dataset{Name: "fresh"}, nil); err != nil {
		fmt.Fprintf(os.Stderr, "register into empty import: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("\nempty document imported as a ready-to-register graph holding %q\n", "fresh")

	// Document problems fail the whole import with nil results, never a
	// partial graph: empty text, an edge endpoint not listed in nodes, and a
	// dependency cycle.
	importFail := func(label, doc string) {
		g, err := chainledger.ImportLineage(doc)
		if err == nil {
			fmt.Fprintf(os.Stderr, "%s unexpectedly succeeded: %v\n", label, g)
			os.Exit(1)
		}
		fmt.Printf("%s refused: %v\n", label, err)
	}
	fmt.Println()
	importFail("empty text", "")
	importFail("missing endpoint", `{"nodes":["a","b"],"edges":[{"from":"a","to":"ghost"}]}`)
	importFail("self dependency", `{"nodes":["a"],"edges":[{"from":"a","to":"a"}]}`)
	importFail("three-node cycle",
		`{"nodes":["a","b","c"],"edges":[`+
			`{"from":"a","to":"b"},{"from":"b","to":"c"},{"from":"c","to":"a"}]}`)
}

package chainledger

import (
	"fmt"
	"reflect"
	"strings"
	"testing"
)

// Statistics carried in extra fields are annotations, not lineage. A JSON number
// in an extra field is accepted purely on its JSON syntax: whether it is
// representable as a float64 is irrelevant, because extra values are never
// decoded into statistics or stored as dataset metadata. This regression guard
// pins that contract against a stricter float-based decoder: numbers that
// overflow (1e400, -1e400), underflow (1e-400) or refuse to round-trip through
// a float64 (a hundred-plus-digit integer) must all import wherever extra
// fields are allowed — at the top level, directly on a dependency object, and
// nested to any depth inside annotation objects and arrays.
func TestImportLineageAcceptsLargeNonFloatableNumbersInExtraFields(t *testing.T) {
	hugeInteger := strings.Repeat("9", 120) // far beyond int64 and float64 precision
	literals := []string{
		"1e400",     // positive overflow in exponential notation
		"-1e400",    // negative overflow in exponential notation
		"1e-400",    // positive underflow (rounds to zero in float64)
		"-1e-400",   // negative underflow
		"1E400",     // capital-E spelling is the same JSON syntax
		"1.5e300",   // finite but at the edge of the float64 range
		hugeInteger, // 120-digit integer, no exponent
		"-" + hugeInteger,
		strings.Repeat("1234567890", 11), // 110 digits alternating digits
	}

	// Every position is an "extra" location: the literal must not be read as a
	// node name or an edge endpoint, and the declared chain is all that lands in
	// the graph.
	positions := []struct {
		name string
		doc  func(lit string) string
	}{
		{
			"top-level extra field",
			func(lit string) string {
				return `{"nodes":["raw","mid","report"],"edges":[` +
					`{"from":"raw","to":"mid"},{"from":"mid","to":"report"}],` +
					`"stat":` + lit + `}`
			},
		},
		{
			"extra field first in a dependency object",
			func(lit string) string {
				return `{"nodes":["raw","mid","report"],"edges":[` +
					`{"stat":` + lit + `,"from":"raw","to":"mid"},` +
					`{"from":"mid","to":"report"}]}`
			},
		},
		{
			"extra field last in a dependency object",
			func(lit string) string {
				return `{"nodes":["raw","mid","report"],"edges":[` +
					`{"from":"raw","to":"mid"},{"from":"mid","to":"report","stat":` + lit + `}]}`
			},
		},
		{
			"nested annotation object",
			func(lit string) string {
				return `{"nodes":["raw","mid","report"],"edges":[` +
					`{"from":"raw","to":"mid"},{"from":"mid","to":"report"}],` +
					`"note":{"stats":{"rows":` + lit + `}}}`
			},
		},
		{
			"nested annotation array",
			func(lit string) string {
				return `{"nodes":["raw","mid","report"],"edges":[` +
					`{"from":"raw","to":"mid"},{"from":"mid","to":"report"}],` +
					`"note":{"stats":[` + lit + `]}}`
			},
		},
		{
			"array of nested objects",
			func(lit string) string {
				return `{"nodes":["raw","mid","report"],"edges":[` +
					`{"from":"raw","to":"mid"},{"from":"mid","to":"report"}],` +
					`"tags":[{"rows":` + lit + `}]}`
			},
		},
		{
			"deeply interleaved objects and arrays",
			func(lit string) string {
				return `{"nodes":["raw","mid","report"],"edges":[` +
					`{"from":"raw","to":"mid"},{"from":"mid","to":"report"}],` +
					`"note":{"outer":[{"inner":[[` + lit + `],{"deep":` + lit + `}]}]}}`
			},
		},
		{
			"bare numeric array elements",
			func(lit string) string {
				return `{"nodes":["raw","mid","report"],"edges":[` +
					`{"from":"raw","to":"mid"},{"from":"mid","to":"report"}],` +
					`"stats":[0,` + lit + `,-0]}`
			},
		},
	}

	for _, lit := range literals {
		for _, pos := range positions {
			name := lit
			if len(name) > 12 {
				name = name[:5] + "...(" + fmt.Sprintf("%d", len(lit)) + "-digit)"
			}
			t.Run(name+"/"+pos.name, func(t *testing.T) {
				graph := mustImport(t, pos.doc(lit))
				assertConsistent(t, graph)
				if got, want := len(graph), 3; got != want {
					t.Fatalf("graph has %d nodes %v, want exactly the declared chain of %d", got, graph, want)
				}
				assertEntry(t, graph, "raw", nil, []string{"mid"})
				assertEntry(t, graph, "mid", []string{"raw"}, []string{"report"})
				assertEntry(t, graph, "report", []string{"mid"}, nil)

				// The literal is annotation data: no dataset is named after it,
				// and the export of the chain carries no trace of the number.
				if _, ok := graph[lit]; ok {
					t.Fatalf("the statistic literal %q became a dataset node", lit)
				}
				out := mustExport(t, graph, "report")
				if want := `{"nodes":["mid","raw","report"],"edges":[{"from":"mid","to":"report"},` +
					`{"from":"raw","to":"mid"}]}`; out != want {
					t.Errorf("export = %s, want %s", out, want)
				}
				if strings.Contains(out, "e400") || strings.Contains(out, "e-400") ||
					strings.Contains(out, "stats") || strings.Contains(out, "note") {
					t.Errorf("export leaked annotation data: %s", out)
				}
			})
		}
	}
}

// The full mixed scenario: source reaches report both directly and through the
// longer source -> b -> mid -> report branch, while a sits on a second
// two-edge branch and isolated is declared independently. Extra fields carry
// large statistics at the top level, on the dependency objects themselves, and
// deep inside annotation objects and arrays, alongside other dataset names and
// from/to-looking objects. Changing the statistic values or moving the fields
// around must change nothing: graph, direct upstream/downstream relations, the
// shortest-path query choice (the direct edge, distance one), the longer
// branch's survival in the full upstream closure, both exports, and their
// ordering. The explicitly listed independent dataset stays; annotation names
// never become nodes or relations; no statistic is stored as metadata.
func TestImportLineageExtraStatisticsLeaveLineageQueriesAndExportsIdentical(t *testing.T) {
	huge1 := strings.Repeat("9", 120)
	huge2 := strings.Repeat("7", 131)

	baseline := `{"nodes":["source","a","b","mid","report","isolated"],"edges":[` +
		`{"from":"source","to":"report"},` +
		`{"from":"source","to":"a"},{"from":"a","to":"report"},` +
		`{"from":"source","to":"b"},{"from":"b","to":"mid"},{"from":"mid","to":"report"}]}`

	// Every variant declares exactly the same lineage as baseline; they differ
	// only in where the annotations sit and which statistic values they carry.
	variants := []struct {
		name string
		text string
	}{
		{
			"stats object before nodes",
			`{"stats":{"rows":1e400,"negative":-1e400,"tiny":1e-400,"huge":` + huge1 + `},` +
				`"nodes":["source","a","b","mid","report","isolated"],"edges":[` +
				`{"from":"source","to":"report"},` +
				`{"from":"source","to":"a"},{"from":"a","to":"report"},` +
				`{"from":"source","to":"b"},{"from":"b","to":"mid"},{"from":"mid","to":"report"}]}`,
		},
		{
			"statistics carried directly by dependency objects",
			`{"nodes":["source","a","b","mid","report","isolated"],"edges":[` +
				`{"weight":1e400,"from":"source","to":"report"},` +
				`{"from":"source","to":"a"},{"from":"a","to":"report","confidence":1e-400},` +
				`{"from":"source","to":"b","meta":{"count":` + huge1 + `}},` +
				`{"from":"b","to":"mid"},{"from":"mid","to":"report","delta":-1e400}]}`,
		},
		{
			"deep annotations after edges with decoy dataset names and relations",
			`{"nodes":["source","a","b","mid","report","isolated"],"edges":[` +
				`{"from":"source","to":"report"},` +
				`{"from":"source","to":"a"},{"from":"a","to":"report"},` +
				`{"from":"source","to":"b"},{"from":"b","to":"mid"},{"from":"mid","to":"report"}],` +
				`"notes":{"summary":"statistics live here","datasets":["ghost","phantom"],` +
				`"relation":{"from":"ghost","to":"phantom"},` +
				`"history":[{"from":"phantom","to":"ghost","rows":[1e-400,` + huge1 + `,-1e400]}],` +
				`"deep":{"layers":[{"values":[[1e400],{"score":-1e-400}]}]}}}`,
		},
		{
			"reordered fields with changed statistic values",
			`{"edges":[{"from":"source","to":"a"},{"from":"a","to":"report"},` +
				`{"from":"source","to":"b"},{"from":"b","to":"mid"},{"from":"mid","to":"report"},` +
				`{"from":"source","to":"report"}],` +
				`"notes":{"n":1e401,"m":-1e401,"arr":[[1e-401,` + huge2 + `]]},` +
				`"nodes":["isolated","report","mid","b","a","source"]}`,
		},
		{
			"bare numeric members at the top level",
			`{"nodes":["source","a","b","mid","report","isolated"],"edges":[` +
				`{"from":"source","to":"report"},` +
				`{"from":"source","to":"a"},{"from":"a","to":"report"},` +
				`{"from":"source","to":"b"},{"from":"b","to":"mid"},{"from":"mid","to":"report"}],` +
				`"total":1e400,"ratio":1e-400,"count":` + huge2 + `}`,
		},
	}

	wantGraph := mustImport(t, baseline)
	wantSnapshot := snapshot(wantGraph)

	// The full upstream export keeps every branch and the existing node/edge
	// ordering, with no statistics anywhere.
	wantExport := `{"nodes":["a","b","mid","report","source"],"edges":[` +
		`{"from":"a","to":"report"},{"from":"b","to":"mid"},` +
		`{"from":"mid","to":"report"},{"from":"source","to":"a"},` +
		`{"from":"source","to":"b"},{"from":"source","to":"report"}]}`
	if got := mustExport(t, wantGraph, "report"); got != wantExport {
		t.Fatalf("baseline export = %s, want %s", got, wantExport)
	}
	if got := mustExportScoped(t, wantGraph, "source", "report"); got != wantExport {
		t.Fatalf("baseline scoped export = %s, want %s", got, wantExport)
	}

	for _, variant := range variants {
		t.Run(variant.name, func(t *testing.T) {
			graph := mustImport(t, variant.text)
			assertConsistent(t, graph)

			// Same lineage result regardless of statistic values or placement:
			// snapshot equality also proves no statistic survives as dataset
			// metadata on any entry.
			if got := snapshot(graph); !reflect.DeepEqual(got, wantSnapshot) {
				t.Fatalf("annotated graph %v, want the baseline graph %v", got, wantSnapshot)
			}
			if got, want := len(graph), 6; got != want {
				t.Fatalf("graph has %d nodes, want %d declared datasets", got, want)
			}

			// Direct relations survive unchanged in both directions, including
			// the direct source -> report edge and the longer branch edges.
			assertEntry(t, graph, "source", nil, []string{"a", "b", "report"})
			assertEntry(t, graph, "a", []string{"source"}, []string{"report"})
			assertEntry(t, graph, "b", []string{"source"}, []string{"mid"})
			assertEntry(t, graph, "mid", []string{"b"}, []string{"report"})
			assertEntry(t, graph, "report", []string{"a", "mid", "source"}, nil)
			assertEntry(t, graph, "isolated", nil, nil)

			// The independent dataset explicitly listed in nodes is retained.
			if got, want := Roots(graph), []string{"isolated", "source"}; !reflect.DeepEqual(got, want) {
				t.Errorf("Roots = %v, want %v", got, want)
			}

			// Names and from/to-looking relations seen only inside annotations
			// are neither nodes nor edges.
			for _, leaked := range []string{"ghost", "phantom", "stats", "notes", "relation"} {
				if _, ok := graph[leaked]; ok {
					t.Errorf("annotation content %q leaked into the graph", leaked)
				}
				if _, err := Impacts(graph, leaked); err == nil ||
					!strings.Contains(err.Error(), leaked) {
					t.Errorf("query for annotation name %q must fail as unregistered, got %v", leaked, err)
				}
			}

			// Downstream impact keeps choosing the direct route at distance one.
			impacts := mustImpacts(t, graph, "source")
			assertImpactOnce(t, impacts, "report", 1, []string{"source", "report"})
			assertImpactOnce(t, impacts, "a", 1, []string{"source", "a"})
			assertImpactOnce(t, impacts, "b", 1, []string{"source", "b"})
			assertImpactOnce(t, impacts, "mid", 2, []string{"source", "b", "mid"})

			// The full upstream closure still carries the longer branch through
			// b and mid even though source reaches report directly.
			upstreams := mustUpstreams(t, graph, "report")
			assertUpstreamOnce(t, upstreams, "source", 1, []string{"source", "report"})
			assertUpstreamOnce(t, upstreams, "a", 1, []string{"a", "report"})
			assertUpstreamOnce(t, upstreams, "mid", 1, []string{"mid", "report"})
			assertUpstreamOnce(t, upstreams, "b", 2, []string{"b", "mid", "report"})

			// Both exports are byte-identical to the annotation-free document:
			// same sorting, same branches, no statistics.
			if got := mustExport(t, graph, "report"); got != wantExport {
				t.Errorf("full export = %s, want %s", got, wantExport)
			}
			if got := mustExportScoped(t, graph, "source", "report"); got != wantExport {
				t.Errorf("scoped export = %s, want %s", got, wantExport)
			}
		})
	}
}

// Ignoring extra fields never means tolerating a malformed document. A number
// that is illegal JSON — an unfinished exponent, an exponent sign with no
// digits, a superfluous leading zero — fails the whole import at any extra
// position with a document-format error and a nil graph. A legal large number
// elsewhere in the same document does not rescue the illegal one, and a legal
// number alone never fails: legal and illegal literals must not be conflated.
func TestImportLineageRejectsMalformedJSONNumbersInExtraFields(t *testing.T) {
	const chain = `{"nodes":["raw","mid","report"],"edges":[` +
		`{"from":"raw","to":"mid"},{"from":"mid","to":"report"}]`
	cases := []struct {
		name string
		text string
	}{
		{"unfinished exponent at top level", chain + `,"bad":1e}`},
		{"capital-E unfinished exponent", chain + `,"bad":3E}`},
		{"exponent sign without digits", chain + `,"bad":1e+}`},
		{"negative exponent without digits", chain + `,"bad":2e-}`},
		{"leading zero at top level", chain + `,"bad":01}`},
		{"negative leading zero", chain + `,"bad":-01}`},
		{"two decimal points", chain + `,"bad":1.2.3}`},
		{"leading zero before a decimal point", chain + `,"bad":00.5}`},
		{"leading zero in a nested object", chain + `,"note":{"bad":01}}`},
		{"unfinished exponent in a nested object", chain + `,"note":{"bad":1e}}`},
		{"leading zero in a nested array", chain + `,"note":{"vals":[01]}}`},
		{"unfinished exponent inside an array of objects", chain + `,"tags":[{"x":1e}]}`},
		{"illegal number inside a dependency object",
			`{"nodes":["raw","mid","report"],"edges":[` +
				`{"from":"raw","to":"mid","x":01},{"from":"mid","to":"report"}]}`},
		{"illegal number deep inside arrays", chain + `,"note":{"outer":[[[{"x":1e}]]]}}`},
		{"legal big number does not rescue malformed sibling",
			chain + `,"stats":{"ok":1e400,"bad":01}}`},
		{"malformed top-level number beside a legal nested one",
			`{"nodes":["raw"],"edges":[],"ok":{"x":1e-400},"bad":-01}`},
		{
			"valid nodes and edges registered before the bad number",
			`{"nodes":["raw","a","b","mid","report","isolated"],"edges":[` +
				`{"from":"raw","to":"a"},{"from":"a","to":"mid"},{"from":"mid","to":"report"},` +
				`{"from":"raw","to":"report"}],"stats":{"rows":1e400},"bad":01}`,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			// The graph must be nil: a format failure can never hand back a map
			// in which the valid nodes listed before the error were registered.
			assertImportFails(t, tc.text, "complete JSON object")
		})
	}

	// Explicit legal/illegal contrast with identical structure: only the
	// malformed spelling fails, and the failure returns nil rather than the
	// already-declared chain.
	legal := chain + `,"stats":{"rows":1e400}}`
	graph := mustImport(t, legal)
	if got, want := len(graph), 3; got != want {
		t.Fatalf("legal document imported %d nodes %v, want %d", got, graph, want)
	}
	returned, err := ImportLineage(chain + `,"stats":{"rows":01}}`)
	if err == nil {
		t.Fatalf("malformed number imported successfully: %v", returned)
	}
	if returned != nil {
		t.Fatalf("malformed number returned a partial graph %v, want nil", returned)
	}
	if !strings.Contains(err.Error(), "complete JSON object") {
		t.Fatalf("error %q must describe the document format problem", err)
	}
}

// A duplicated key stays a duplicated key even when both values are legal large
// numbers that a float64 could never hold. The document must be rejected with a
// nil graph and an error naming the repeated key; last-value-wins semantics are
// not accepted at any nesting depth, including on dependency objects.
func TestImportLineageRejectsDuplicateKeysWithLargeNumberValues(t *testing.T) {
	huge := strings.Repeat("9", 120)
	cases := []struct {
		name string
		text string
		key  string
	}{
		{
			"positive and negative overflow as duplicate values",
			`{"nodes":["raw","report"],"edges":[{"from":"raw","to":"report"}],` +
				`"stats":{"rows":1e400,"rows":-1e400}}`,
			"rows",
		},
		{
			"identical underflow values still duplicate",
			`{"nodes":["raw"],"edges":[],"stats":{"rows":1e-400,"rows":1e-400}}`,
			"rows",
		},
		{
			"two hundred-digit integers as duplicate values",
			`{"nodes":["raw"],"edges":[],"stats":{"rows":` + huge + `,"rows":` + huge + `}}`,
			"rows",
		},
		{
			"duplicate inside an array element object",
			`{"nodes":["raw"],"edges":[],"tags":[{"rows":` + huge + `,"rows":1e400}]}`,
			"rows",
		},
		{
			"duplicate nested deeply among arrays",
			`{"nodes":["raw"],"edges":[],"notes":{"outer":[{"inner":[{"rows":-1e400,"rows":-1e-400}]}]}}`,
			"rows",
		},
		{
			"duplicate key on a dependency object",
			`{"nodes":["raw","report"],"edges":[{"from":"raw","to":"report",` +
				`"weight":1e400,"weight":1e-400}]}`,
			"weight",
		},
		{
			"duplicate top-level members carrying large numbers",
			`{"nodes":["raw"],"edges":[],"count":1e400,"count":1e-400}`,
			"count",
		},
		{
			"later member repeats an earlier large-integer member",
			`{"nodes":["raw","mid","report"],"edges":[` +
				`{"from":"raw","to":"mid"},{"from":"mid","to":"report"}],` +
				`"total":` + huge + `,"other":1,"total":-1e400}`,
			"total",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			assertImportFails(t, tc.text, "duplicated", tc.key)
		})
	}
}

